using System.Diagnostics;
namespace ToneCustoms.ShellStudio.Bridges;
public sealed record BlenderRunResult(int ExitCode,string StdOut,string StdErr);
public sealed class BlenderBridge { public async Task<BlenderRunResult> RunHeadlessAsync(string blender,string? blend,string script,params string[] args){var psi=new ProcessStartInfo(blender){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true};psi.ArgumentList.Add("--background");if(!string.IsNullOrWhiteSpace(blend))psi.ArgumentList.Add(blend);psi.ArgumentList.Add("--python");psi.ArgumentList.Add(script);psi.ArgumentList.Add("--");foreach(var a in args)psi.ArgumentList.Add(a);using var p=Process.Start(psi)??throw new InvalidOperationException("Unable to start Blender");var stdout=p.StandardOutput.ReadToEndAsync();var stderr=p.StandardError.ReadToEndAsync();await p.WaitForExitAsync();return new(p.ExitCode,await stdout,await stderr);} }
